class Solution {
public:
    int maxOperations(vector<int>& nums, int k) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        int ans = 0;
        for (auto& [x, c] : cnt) {
            int y = k - x;
            if (y < x) continue;
            if (y == x) {
                ans += c / 2;
            } else {
                auto it = cnt.find(y);
                if (it != cnt.end()) {
                    ans += min(c, it->second);
                }
            }
        }
        return ans;
    }
};
